void setup() {
    // Inicializa la comunicación serie a 9600 baudios (velocidad del módulo)
    Serial.begin(9600);
}

void loop() {
    // Verifica si llegaron datos desde el Bluetooth
    if (Serial.available()) {
        // Lee el caracter recibido
        char dato = Serial.read();

        // Devuelve una confirmación
        Serial.print("Recibido: ");
        Serial.println(dato);
    }
}
